    func rect(_ x: CGFloat, _ y: CGFloat, _ w: CGFloat, _ h: CGFloat) -> CGRect {
        CGRect(origin: point(x, y + h), size: CGSize(width: w, height: h))
    }

    func color(_ c: Color) -> CGColor {
        CGColor(red: c.0, green: c.1, blue: c.2, alpha: 1)
    }

    @discardableResult
    func label(_ s: String, _ x: CGFloat, _ y: CGFloat, _ size: CGFloat,
               _ face: String = sans, _ tone: Color = ink, tracking: CGFloat = 0,
               maxWidth: CGFloat? = nil) -> CGFloat {
        let attrs: [NSAttributedString.Key: Any] = [
            NSAttributedString.Key(kCTFontAttributeName as String):
                CTFontCreateWithName(face as CFString, size, nil),
            NSAttributedString.Key(kCTForegroundColorAttributeName as String): color(tone),
            NSAttributedString.Key(kCTKernAttributeName as String): tracking
        ]
        let line = CTLineCreateWithAttributedString(NSAttributedString(string: s, attributes: attrs))
        let width = CGFloat(CTLineGetTypographicBounds(line, nil, nil, nil))
        if let maxWidth {
            precondition(width <= maxWidth, \"\\(s) is \\(width) pt wide, with \\(maxWidth) pt available.\")
        }
        context.textMatrix = .identity
        context.textPosition = point(x, y)
        CTLineDraw(line, context)
        return width
    }

    func path(_ tone: Color, _ width: CGFloat, _ build: (CGMutablePath) -> Void) {
        let path = CGMutablePath()
        build(path)
        context.setStrokeColor(color(tone))
        context.setLineWidth(width)
        context.setLineCap(.round)
        context.setLineJoin(.round)
        context.addPath(path)
        context.strokePath()
    }

    func line(_ x1: CGFloat, _ y1: CGFloat, _ x2: CGFloat, _ y2: CGFloat,
              _ tone: Color = ruling, _ width: CGFloat = 0.7) {
