func pdf(_ name: String, width: CGFloat, height: CGFloat, title: String,
         draw: (Canvas) -> Void) {
    let url = URL(fileURLWithPath: CommandLine.arguments[1]).appendingPathComponent(name)
    var bounds = CGRect(x: 0, y: 0, width: width, height: height)
    let metadata = [kCGPDFContextTitle: title] as CFDictionary
    guard let context = CGContext(url as CFURL, mediaBox: &bounds, metadata) else {
        fatalError("Cannot write '"\\(name)\")
    }
    context.beginPDFPage(nil)
    draw(Canvas(context: context, pageHeight: height))
    context.endPDFPage()
    context.closePDF()
}

func childPDF(_ paper: String, _ width: CGFloat, _ height: CGFloat) {
    pdf(\"Child Journal - \\(paper).pdf\", width: width, height: height,
        title: \"Canal Shape Walk | Child Journal\") { canvas in
        let half = width / 2
        let inset = (half - 396) / 2
        let top = (height - 595) / 2
        var card = canvas
        card.xOffset = inset
        card.yOffset = top
        card.journal()
        card.xOffset += half
        card.journal()
        canvas.context.setLineDash(phase: 0, lengths: [3, 4])
        canvas.line(half, 19, half, height-19, ruling, 0.55)
        canvas.context.setLineDash(phase: 0, lengths: [])
    }
}

